    [2278] = "Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon.",
    [2279] = "Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Forgefer.",
    [2280] = "Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff.",
    [2283] = "Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé.",
    [2284] = "Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes.",
    [2318] = "Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates.",
    [2338] = "Laisser Jarkal emprunter le Collier en échange de la traduction du Journal.",
    [2339] = "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.$B$BC'est dans le journal, vous savez...$B* Le rubis a été caché dans une zone barricadée des Ombreforge.$B* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.$B* Le saphir est possession du chef trogg, Grimlok.",
    [2340] = "Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar.",
    [2341] = "Rendre visite à Jarkal Mossmeld à Kargath pour constater (ou non) son succès.",
    [2342] = "Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman.",
    [2359] = "Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Hurlevent. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.",
    [2360] = "Se rendre dans la marche de l'Ouest et trouver l'Agent Kearnen pour un débriefing.",
    [2361] = "C'est avec joie que je vous donne ce collier, $C. Vous m'avez rendu un service inestimable. Portez-le avec fierté et n'hésitez pas à citer fréquemment et à voix haute le nom du fabriquant !$B$BEt si vous pouviez préciser au passage qu'il n'est pas maudit, ce serait parfait.",
    [2398] = "Trouver Baelog dans Uldaman.",
    [2418] = "Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates.",
    [2439] = "Apporter le Bon de récompense à Dinita Stonemantle à la Chambre forte de Forgefer.",
    [2440] = "Apporter le Bon de récompense à Bena Winterhoof à Thunder Bluff.",
    [2458] = "Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule.$B$BUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).$B$BRespecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier.",
    [2460] = "Faire le Salut brisé à Shenthul.",
    [2478] = "Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.$B$BAssassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.",
    [2479] = "Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.$B$BPour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !",
    [2480] = "Attendre Serge Hinott pour achever le remède.",
    [2607] = "Aller voir le docteur Mixilpixil dans la Cave de la caserne.",
    [2608] = "S'allonger (/coucher) pour être $Gexaminé:examinée; par le docteur Mixilpixil. Comment peut-il trouver le remède s'il ne peut pas trouver la cause ?",
    [2609] = "Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul.",
    [2621] = "Aller voir le commandant d'ordonnance Ruag dans Pierrêche.",
    [2622] = "Aller voir Bengor.",
    [2623] = "Retrouver les Ordres du Chef de guerre et les rendre au Héros déchu de la Horde.",
    [2681] = "Libérer 9 Serviteurs de Razelikh, 3 Serviteurs de Sevine, 3 Serviteurs d'Allistarj et 3 Serviteurs de Grol. Retourner voir le Héros déchu une fois la tâche terminée. Il faut rester à proximité des pierres ou le processus échouera.",
    [2701] = "Ouvrir le coffre et prendre la récompense.",
    [2702] = "Aller voir le caporal Thund Splithoof.",
    [2721] = "Découvrir ce qui est arrivé au Lieutenant Kirith.",
    [2743] = "Retourner voir le Héros déchu de la Horde avec ces découvertes.",
    [2744] = "Aller voir Loramus Thalipedes à Azshara.",
    [2745] = "Aller voir Tyrion au Château de Hurlevent.",
    [2746] = "Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Hurlevent.",
    [2768] = "Rapporter le Bâtonnet divino-matic à l'Ingénieur en chef Bilgewhizzle, à Gadgetzan.",
    [2770] = "Rapporter les Ecailles électrifiées de Gahz'rilla à Wizzle Brassbolts dans les Salines.",
    [2783] = "Parler au Héros déchu de la Horde à la frontière des Terres foudroyées et du marais.",
    [2784] = "Écouter le Héros déchu de la Horde raconter son histoire.",
    [2801] = "Écouter le Héros déchu de la Horde raconter son histoire.",
    [2846] = "Rapporter la Tiare des abysses à Tabetha au marécage d'Âprefange.",
    [2861] = "Parler à Tabetha dans le marécage d'Âprefange.",
    [2864] = "Parler à Tran'rek à Gadgetzan.",
    [2865] = "Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan.",
    [2936] = "Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Witherbark, puis retourner voir Maître Gadrin.",
    [2983] = "Trouver Kranal Fiss dans les Tarides.",
    [2984] = "Trouver Kranal Fiss dans les Tarides.",
    [2985] = "Trouver Islen Waterseer dans les Tarides.",
    [2986] = "Trouver Islen Waterseer dans les Tarides.",
    [2991] = "Apporter le Médaillon de Nekrum à Thadius Grimshade, dans les Terres foudroyées.",
    [3001] = "Trouver Strahad Farsan, à Ratchet.",
    [3042] = "Apporter 20 Fioles d'agent durcissant troll à Trenton Lighthammer, dans Gadgetzan.",
    [3141] = "Écouter l'histoire de Loramus Thalipedes.",
    [3369] = "Apporter l'Eclat de cauchemar à Hamuul Runetotem à la Cime des Anciens.",
    [3370] = "Apporter l'Eclat de cauchemar à Mathrengyl Bearwalker à Darnassus.",
    [3373] = "Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti.",
    [3380] = "Trouver Marvon Rivetseeker à Tanaris.",
    [3446] = "Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins.",
    [3447] = "Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues.",
    [3504] = "Apporter la Lettre Scellée à Ag'tor Bloodfist dans Azshara.",
    [3505] = "Tuez 6 vengeurs elfes de sang et 6 géomètres elfes de sang avant de chercher la source du pouvoir de Rimtori.",
    [3508] = "Attendre que Loramus ait achevé le rituel de Lumière.",
    [3509] = "Aller voir le seigneur Arkkoroc dans Azshara. Commencer la recherche au bord de l'eau pour trouver le temple d'Arkkoran.",
    [3510] = "Assassiner Hetaera et apporter la Tête ensanglantée d'Hetaera, la Tête battue d'Hetaera et la Tête meurtrie d'Hetaera au seigneur Arkkoroc.",
    [3511] = "Rapporter le durcisseur à Loramus Thalipedes.",
    [3520] = "Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression.",
    [3527] = "Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris.",
    [3528] = "Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris.",
    [3602] = "Trouver 20 Azsharites cristallisées au sud d'Azshara. Utiliser éventuellement le gangrechien pour ‘renifler’ l'emplacement où sont intelligemment cachés les dépôts.$B$BRetourner voir Loramus une fois votre tâche accomplie.",
    [3621] = "Apporter la cargaison à Galvan l'Ancien dans la vallée de Strangleronce.",
    [3625] = "Attendre que Galvan ait fini de forger les armes.",
    [3626] = "Retourner voir le Héros déchu de la Horde.",
    [3627] = "Assassiner Grol le Destructeur, dame Sevine et l'archimage Allistarj. Prendre sur leurs cadavres l'Amulette de Grol, l'Amulette de Sevine et l'Amulette d'Allistarj.$B$BUTILISER les armes Fel en Azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais les utiliser sagement...",
    [3628] = "Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros déchu de la Horde. Rendre aussi l'Amulette du Souilleur au Héros Déchu pour qu'il puisse la détruire, afin de l'empêcher de tomber dans de mauvaises mains.",
    [3631] = "Parler à Strahad Farsan, dans les Tarides.",
    [3701] = "Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus.",
    [3702] = "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan.",
    [3783] = "Collecter 10 Fourrures épaisses de yéti pour Umi Rumplesnicker, à Long-guet.",
    [3801] = "Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse.",
    [3802] = "Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright.",
    [3844] = "Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé.",
    [3845] = "Examiner les objets du paquet et les apporter à leur propriétaire.",
    [3903] = "Parler à Milly Osworth.",
    [3904] = "Apporter 8 seaux de la récolte de Milly à Milly Osworth à l’abbaye de Comté-du-Nord.",
    [3907] = "Pénétrer dans les Profondeurs de Rochenoire et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.",
    [3908] = "Apporter l’Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver.",
    [3909] = "Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver.",
    [3912] = "Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.",
    [3913] = "Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver.",
    [3914] = "Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro.",
    [3941] = "Trouver J.D. Collie dans la caverne du refuge des Marshal.",
    [3942] = "Trouver Eridan Bluewind dans le sud de Gangrebois.",
    [3961] = "Apporter le Totem d'argent d'Aquementas à Linken au refuge des Marshal.",
    [3962] = "Partir pour la crête de la Fournaise, au sud du refuge des Marshal.$B$BTrouver Blazerunner et utiliser le Totem pour dissiper son aura protectrice. Une fois Blazerunner vaincu, se procurer la Flamme dorée.",
    [3981] = "Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.$B$BLe dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison.",
    [3982] = "Défendre Gor'shak.",
    [4001] = "Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar.$B$BGor'shak a dit que Kharan était détenu dans une cellule proche.",
    [4002] = "Parler à Thrall si vous êtes $Gprêt:prête; à vous charger de la mission qu'il a prévue.",
    [4003] = "Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique.",
    [4004] = "Retourner voir Thrall !",
    [4005] = "Apporter le Livre d'Aquor, les Griffes argentées et le Coeur d'Arbrefer à Tanaris.$B$BUtiliser le Livre d'Aquor pour invoquer Aquementas.$B$BAprès avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal.",
    [4024] = "Partir pour les Profondeurs de Rochenoire et tuer Bael'Gar.$B$BVous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.$B$BApporter l'Essence ardente recouverte à Cyrus Therepentous.",
    [4063] = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.",
    [4081] = "Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs !$B$BLe chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.",
    [4082] = "Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs !$B$BLe Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie.",
    [4083] = "Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant.",
    [4084] = "Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Bluewind à Gangrebois.",
    [4121] = "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Rochenoire, jusqu'à la gorge des Vents brûlants.$B$BRappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.$B$BOn vous demandera également de remettre vos chaînes en thorium à Lexlort.",
    [4122] = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Rochenoires.$B$BUne fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Rochenoire jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde.",
    [4123] = "Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes.",
    [4124] = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.",
    [4125] = "Localiser le bateau du messager quelque part le long de la côte de Feralas.",
    [4126] = "Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos.",
    [4127] = "Retourner au bastion de Feathermoon et montrer à Ginro Hearthkindle le Couteau perdu que vous avez découvert.",
    [4128] = "Parler à Ragnar Thunderbrew.",
    [4129] = "Apporter le Couteau perdu à Quintis Jonespyre au bastion de Feathermoon.",
    [4130] = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.",
    [4131] = "Fouiller les Camps des gnolls Griffebois dans la partie sud de Feralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même.",
    [4132] = "Voyagez jusqu'aux Profondeurs de Rochenoire et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.",
    [4133] = "Parler à la maîtresse des ombres Vivian Lagrave à Kargath.",
    [4134] = "Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath.",
    [4135] = "À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois.",
    [4136] = "Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes.",
    [4182] = "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie.",
    [4183] = "Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon.",
    [4184] = "Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.$B$BBolvar demeure dans le Donjon de Stormwind.",
    [4185] = "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor.",
    [4186] = "Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire.",
    [4201] = "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Rochenoire.",
    [4223] = "Parler au maréchal Maxwell dans les Steppes ardentes.",
    [4224] = "Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.$B$BVous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord.",
    [4241] = "Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor.$B$BVous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison.",
    [4242] = "Donner les mauvaises nouvelles au maréchal Maxwell.",
    [4263] = "Trouver le Seigneur Incendius dans les Profondeurs de Rochenoire et le détruire !",
    [4264] = "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…",
    [4265] = "Libérer Raschal de la ruche de Zukk'ash.$B$BRevenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf.",
    [4266] = "Parler à Shandris Feathermoon dans le bastion de Feathermoon.",
    [4267] = "Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus.",
    [4281] = "Apporter le Vieux colis à Falfindel Waywarder, à Thalanaar.",
    [4282] = "Rapporter les Renseignements perdus du maréchal Windsor.$B$BLe maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne.",
    [4286] = "Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire.",
    [4322] = "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell.",
    [4324] = "Parler à Yuka Screwspigot dans les Steppes ardentes.",
    [4341] = "Aller dans les Profondeurs de Blackrock et trouver Kharan Mighthammer.$B$BLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison.",
    [4342] = "Écouter Kharan Mighthammer raconter son histoire.",
    [4361] = "Retourner à Ironforge et apporter la mauvaise nouvelle au Roi Magni Bronzebeard.",
    [4362] = "Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan.",
    [4363] = "Retourner à Ironforge et parler au roi Magni Bronzebeard.",
    [4487] = "Parler à Strahad Farsan, à Ratchet.",
    [4488] = "Parler à Strahad Farsan, à Ratchet.",
    [4489] = "Parler à Strahad Farsan, à Ratchet.",
    [4490] = "Parler à Strahad Farsan, à Ratchet pour apprendre à invoquer un Palefroi corrompu.",
    [4701] = "Allez au pic Rochenoire et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs.",
    [4724] = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe.",
    [4729] = "Aller au pic Rochenoire et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler.",
    [4734] = "Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie.",
    [4735] = "Apporter 8 Oeufs de dragon collectés et le Module collectronique à Tinkee Steamboil à la Corniche des flammes dans les Steppes Ardentes.",
    [4742] = "Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.$B$BLes généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe.",
    [4743] = "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.$B$BA cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !",
    [4764] = "Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes.",
    [4765] = "Apporter la Caisse de Ridgewell à Remington Ridgewell, à Hurlevent.",
    [4766] = "Parler à Mayara Brightwing, dans les Steppes Ardentes.",
    [4768] = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.",
    [4769] = "Parler à l'ombremage Vivian Lagrave.",
    [4771] = "Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink.",
    [4787] = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris.",
    [4788] = "Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris.",
    [4862] = "Aller au pic Rochenoire et ramasser 15 Oeuf d'araignée du pic pour Kibler.$B$BCes oeufs peuvent être trouvés à proximité des araignées.",
    [4866] = "Vous trouverez la Matriarche Couveuse au coeur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois $Gempoisonné:empoisonnée;, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon.",
    [4867] = "Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh.",
    [4903] = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents de Rochenoire. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.",
    [4907] = "Parler à Tinkee Steamboil.",
    [4921] = "Trouver la femme de Mankrik puis retourner le voir à la Croisée.",
    [4941] = "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.$B$BVous avez déjà vu Eitrigg dans les Appartements de Thrall.",
    [4974] = "Aller au pic Rochenoire et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar.",
    [4981] = "Aller au pic Rochenoire et découvrir ce qui est arrivé à Bijou.",
    [4982] = "Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville.",
    [4983] = "Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath.",
    [5001] = "Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !",
    [5002] = "Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell.",
    [5047] = "Parler à Malyfous Darkhammer à Long-guet.",
    [5061] = "Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Bearwalker.",
    [5065] = "Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris.",
    [5081] = "Se rendre au pic Rochenoire et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie.",
    [5089] = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes.",
    [5096] = "Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major.$B$BPlacer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.",
    [5097] = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.$B$BQuand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.",
    [5098] = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.$B$BQuand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.",
    [5102] = "Rendez-vous au pic Rochenoire et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell.",
    [5122] = "Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.$B$BS'il vous plaît, $N, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme.",
    [5125] = "$N, je me meurs… mais mon âme est sauve, et pour cela je vous dois plus que les mots peuvent exprimer. Je vous en prie, prenez ceci… et continuez le combat, brave $C !",
    [5127] = "Se rendre au pic Rochenoire et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.$B$BTrouver aussi la Cuirasse couverte de runes inachevée.$B$BRapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver.",
    [5142] = "Retrouver Pamela Redpath.",
    [5149] = "Trouver la poupée de Pamela.",
    [5152] = "Parler à Marlene, au sud des ruines d'Andorhal.",
    [5153] = "Apporter l’Alliance de Joseph à Chromie.",
    [5154] = "Apporter les Annales de Darrowshire à Chromie, à Andorhal.",
    [5160] = "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee.",
    [5163] = "Prendre le yéti mécanique d'Umi et effrayer ses amis avec :$B$BLegacki, à Long-guet (Berceau-de-l'Hiver)$BSprinkle, à Gadgetzan (Tanaris)$BQuixxil, au refuge des Marshal (Cratère d'Un'Goro)$B$BQuand vous aurez terminé, rapporter le yéti mécanique à Umi.",
    [5168] = "Apporter le Libram de Davil et le Bouclier Redpath à Carlin Redpath.",
    [5181] = "Rapporter le Crâne d'Horgus et l’Epée brisée de Marduk à Carlin Redpath à la chapelle de l'Espoir de Lumière.",
    [5206] = "Apporter 5 Crânes résonants et le Cristal mystique à Carlin Redpath, dans les Maleterres de l’est.",
    [5210] = "Apporter les Annales complètes de Darrowshire à Carlin Redpath dans les Maleterres de l’est.",
    [5211] = "Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath.",
    [5212] = "Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair.",
    [5213] = "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink.",
    [5214] = "Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.",
    [5241] = "Trouver Carlin Redpath.",
    [5243] = "Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.",
    [5251] = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates.",
    [5262] = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est.",
    [5263] = "S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff.",
    [5282] = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !$B$BLibérer 15 Esprits sans repos puis retourner auprès d’Egan.",
    [5341] = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès d’Alexi Barov quand la tâche est accomplie.",
    [5342] = "Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.$B$BAttention : Weldon sera probablement bien protégé par la racaille de l’Alliance.",
    [5343] = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie.",
    [5344] = "Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.$B$BAttention : Alexi sera probablement bien protégé par les vandales de la Horde.",
    [5382] = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie.",
    [5383] = "Apporter le Sac des horreurs à Eva Sarkhoff à Caer Darrow.",
    [5384] = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.$B$BCombattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.",
    [5461] = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke.",
    [5462] = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert.",
    [5463] = "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie.",
    [5464] = "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est.",
    [5465] = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié.",
    [5466] = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.",
    [5514] = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.",
    [5515] = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff.",
    [5518] = "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes.",
    [5525] = "C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…$B$BMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?",
    [5528] = "V’z’êtes le grand patron maintenant, alors z’avez le droit de goûter mes alcools. Ils rendent fort ET font tourner la tête ! C’est d’la bonne, chef… essayez, vous pourrez l’dire à Kreeg !",
    [5529] = "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière.",
    [5531] = "Apporter les Oeufs congelés à Betina Bigglezink.",
    [5533] = "Parler à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5537] = "Apporter 15 Fragments de squelette à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5538] = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.",
    [5582] = "Apporter l’Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.",
    [5601] = "Trouver Pamela Redpath dans le Darrowshire.",
    [5721] = "Placer la Liasse de reliques sur la place centrale de Darrowshire.$B$BEmpêcher la mort de Davil Lightfire, jusqu’à la mort de Horgus.$B$BEmpêcher la mort du capitaine Redpath, jusqu’à ce que Redpath le Corrompu apparaisse.$B$BVaincre Redpath le Corrompu.$B$BParler à l’esprit de Joseph Redpath, quand il apparaît sur la place centrale, puis parler à Pamela, dans sa maison.",
    [5742] = "Écouter ce que Tirion Fordring a à dire.",
    [5762] = "Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce.",
    [5763] = "Apporter la Corne de kodo de Roon à Hemet Nesingwary à Strangleronce.",
    [5781] = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission.",
    [5801] = "Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un'Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée.$B$BApporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5802] = "Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.$B$BApporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, Maleterres de l'Ouest.",
    [5803] = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5804] = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’apothicaire Dithers à la Barricade, dans les Maleterres de l’ouest.",
    [5845] = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.",
    [5846] = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau.",
    [5848] = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.$B$BRapporter le tableau à Tirion Fordring.",
    [5861] = "Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion.",
    [5862] = "Parler à Myranda pour obtenir l’Illusion écarlate. Aller à Hearthglen pendant que vous êtes sous l’effet de l’Illusion écarlate, et apporter le Don de Tirion au généralissime Taelan Fordring.$B$BHearthglen se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde.",
    [5921] = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.",
    [5922] = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.",
    [5923] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5924] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5925] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5926] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5927] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5928] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5929] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [5930] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [5931] = "Retourner à Darnassus et parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne.",
    [5932] = "Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens.",
    [5941] = "Apporter la Liasse de reliques à Chromie, à Andorhal.",
    [5942] = "Utiliser la Clé de Joseph sur le Coffre de Joseph.",
    [5944] = "Escortez Taelan Fordring jusqu'à la sortie des Hearthglen.",
    [6001] = "Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.",
    [6002] = "Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Turak Runetotem, à Thunder Bluff.",
    [6004] = "Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Deepshadow dans les Maleterres de l'ouest.",
    [6023] = "Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.",
    [6025] = "Aller dans Hearthglen, et trouver un poste d’observation élevé d’où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.",
    [6061] = "Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6062] = "Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.",
    [6063] = "Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6064] = "Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos.",
    [6065] = "Parler à Yaw Sharpmane, à Sabot-de-Sang.",
    [6066] = "Parler à Yaw Sharpmane, à Sabot-de-Sang.",
    [6067] = "Parler à Yaw Sharpmane, à Sabot-de-Sang.",
    [6068] = "Parler à Thotar, à Tranchecolline.",
    [6069] = "Parler à Thotar, à Tranchecolline.",
    [6070] = "Parler à Thotar, à Tranchecolline.",
    [6071] = "Parler à Dazalar, à Dolanaar.",
    [6072] = "Parler à Dazalar, à Dolanaar.",
    [6073] = "Parler à Dazalar, à Dolanaar.",
    [6074] = "Parler à Grif Wildheart, à Kharanos.",
    [6075] = "Parler à Grif Wildheart, à Kharanos.",
    [6076] = "Parler à Grif Wildheart, à Kharanos.",
    [6081] = "Adressez-vous à Orkmar Grimshot à Orgrimmar.",
    [6082] = "Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.",
    [6083] = "Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.",
    [6084] = "Domptez un Léopard des neiges à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.",
    [6085] = "Domptez un ours Griffeglace à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.",
    [6086] = "Adressez-vous à Belia Thundergranite à Forgefer.",
    [6087] = "Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6088] = "Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6089] = "Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.",
    [6101] = "Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6102] = "Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6103] = "Parler à Jocaste, à l'enclave cénarienne de Darnassus.",
    [6121] = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.",
    [6122] = "Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes.$B$BApporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage.",
    [6123] = "Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède.",
    [6124] = "Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d’abord entre le sud de la rivière Bondissante et le nord d’Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d’Ashenvale.",
    [6125] = "Retourner voir Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [6126] = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.",
    [6127] = "Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l’eau d’un bassin, au sommet du Pic de Brume-funeste.$B$BApporter ensuite la Fiole d'échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides.",
    [6128] = "Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Runetotem, à la Croisée, pour qu'il puisse préparer un baume curatif.",
    [6129] = "Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.",
    [6130] = "Retourner voir Turak Runetotem, sur la Cime des Anciens, à Thunder Bluff.",
    [6141] = "Adressez-vous au frère Anton, en Désolace.",
    [6144] = "Aller à Undercity et parler à Varimathras.",
    [6145] = "Retourner dans les Maleterres de l’est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand Croisé.$B$BApporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires.",
    [6146] = "Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d’avoir revêtu l’apparence d’un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar.",
    [6147] = "Retourner voir Nathanos le Flétrisseur avec la nouvelle information.",
    [6148] = "La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholm, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur.",
    [6163] = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos.",
    [6402] = "Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée.",
    [6403] = "Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !",
    [6501] = "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe.",
    [6502] = "Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock.",
    [6566] = "Écouter Thrall.",
    [6567] = "Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas.",
    [6568] = "Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest.",
    [6569] = "Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée.",
    [6570] = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre.",
    [6582] = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.$B$BClairvoyant se trouve au Berceau-de-l'Hiver.",
    [6583] = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.",
    [6584] = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.",
    [6585] = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre.",
    [6601] = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.",
    [6602] = "Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar.",
    [6681] = "Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines d'Hillsbrad.$B$BVotre sagacité sera mise à l’épreuve tout au long de la route. Préparez-vous.",
    [6721] = "Parler à Dazalar, à Dolanaar.",
    [6722] = "Parler à Dazalar, à Dolanaar.",
    [6981] = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.$B$BPuis livrez l'Eclat, selon les instructions.",
    [7028] = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace.",
    [7029] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.$B$BEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.$B$BSoigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre.",
    [7041] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.$B$BEn faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.$B$BSoigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel.",
    [7044] = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.$B$BTrouvez un moyen de parler à Celebras.",
    [7046] = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.$B$BParlez-lui après la réussite du rituel.",
    [7064] = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace.",
    [7065] = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace.",
    [7066] = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie.",
    [7067] = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace.",
    [7068] = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar.",
    [7070] = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange.",
    [7201] = "Rejoignez les profondeurs de Rochenoire et trouvez 10 essences des éléments. Commencez vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d’élémentaires.",
    [7441] = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.$B$BSi vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas.",
    [7461] = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.$B$BEntrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.$B$BLorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour.",
    [7462] = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !",
    [7463] = "Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos.",
    [7481] = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.",
    [7482] = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon.",
    [7488] = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas.",
    [7489] = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas.",
    [7490] = "Apportez la Tête d’Onyxia à Thrall à Orgrimmar.",
    [7491] = "Allez voir le seigneur Runthak dans la vallée de la Force.",
    [7492] = "Parlez à Talo Thornhoof au Camp Mojache, en Feralas.",
    [7493] = "Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.$B$BJe vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.$B$BServez-vous des écailles de leur mère pour créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian.",
    [7494] = "Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas.",
    [7495] = "Apportez la Tête d’Onyxia au généralissime Bolvar Fordragon à Hurlevent.",
    [7496] = "Allez voir le major Mattingly dans la vallée des Héros.",
    [7497] = "Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.$B$BJe vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.$B$BServez-vous des écailles de leur mère pour créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian.",
    [7498] = "Rendez ce livre à ses légitimes propriétaires.",
    [7499] = "Rendez ce livre à ses légitimes propriétaires.",
    [7500] = "Rendez ce livre à ses légitimes propriétaires.",
    [7501] = "Rendez ce livre à ses légitimes propriétaires.",
    [7502] = "Rendez ce livre à ses légitimes propriétaires.",
    [7503] = "Rendez ce livre à ses légitimes propriétaires.",
    [7504] = "Rendez ce livre à ses légitimes propriétaires.",
    [7505] = "Rendez ce livre à ses légitimes propriétaires.",
    [7506] = "Rendez ce livre à ses légitimes propriétaires.",
    [7507] = "Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum.",
    [7508] = "Donnez la Lame elfique inachevée au Gardien du savoir Lydros.",
    [7509] = "Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.$B$BAvant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.$B$BSi vous y parvenez, Quel’Serrar sera à vous.",
    [7562] = "Parler à Mor'zul Bloodbringer dans les Steppes ardentes.",
    [7563] = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes.",
    [7564] = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes.",
    [7604] = "Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron.",
    [7623] = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.$B$BServez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow.",
    [7624] = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar.",
    [7625] = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes.",
    [7626] = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes.",
    [7627] = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes.",
    [7628] = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes.",
    [7629] = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes.",
    [7630] = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes.",
    [7631] = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit.",
    [7632] = "Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, $N, le monde est vaste.",
    [7634] = "L'Ancien Hasat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois",
    [7635] = "L’Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois.",
    [7636] = "Vous devez trouver et tuer quatre corrupteurs démoniaques :$B$BSimona la Séductrice.$B$BKlinfran l’Enragé.$B$BSolenor le Tueur.$B$BArtorius le Néfaste.$B$BDétruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois.$B$BVous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire.$B$BVous DEVEZ agir seul.",
    [7637] = "Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or.",
    [7638] = "Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.",
    [7639] = "Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind.",
    [7640] = "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.",
    [7641] = "Parlez à Grimand Elmore dans le Quartier des nains de Stormwind.",
    [7642] = "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind.",
    [7643] = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer.$B$BEnsuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse.",
    [7644] = "Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker.",
    [7645] = "Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits.$B$BVous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité.",
    [7646] = "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.",
    [7647] = "Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.$B$BEnsuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre.",
    [7648] = "Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection.",
    [7703] = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.$B$BSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.",
    [7761] = "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement.$B$BD’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter.",
    [7785] = "Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian.",
    [7786] = "Pour libérer Thunderaan le Cherchevent de sa prison, vous devez présenter au généralissime Demetrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du Seigneur du feu.",
    [7787] = "Présenter la Lame du baiser du vent dormante au généralissime Demitrian.",
    [7877] = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !",
    [8181] = "Parlez à Yeh'kinya.",
    [8182] = "Parlez à Molthor à Strangleronce.",
    [8323] = "L'ermite Ortell veut que vous lui apportiez 10 Textes du crépuscule cryptés.",
    [8410] = "Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents.",
    [8412] = "Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents.",
    [8921] = "Retournez voir Mux Manascrambler à Gadgetzan avec 1 Convertisseur d’arcanite délicat, 4 Essences éternelles supérieures, 10 Huiles de pierre-écaille, 25 Cendres volcaniques et 40 pièces d’or.",
    [8922] = "Remettre le Récipient de sang scellé à Mux Manascrambler, à Gadgetzan en Tanaris.",
    [8923] = "Remettez le Récipient de venin scellé à Mux Manascrambler, à Gadgetzan.",
    [8924] = "Utilisez l’Alambic ectoplasmique à proximité de morts-vivants désincarnés pour recueillir 12 Ectoplasmes brûlés en Silithus, 12 Ectoplasmes glacés au Berceau-de-l’hiver et 12 Ectoplasmes stables dans les Maleterres de l’est. Remettez à Mux Manascrambler à Gadgetzan. Il veut aussi récupérer l'Alambic ectoplasmique.",
    [8925] = "Trouvez le Seigneur-magma Bokk dans les Steppes ardentes, prenez son Coeur de magma et rapportez-le à Mux Manascrambler, à Gadgetzan.",
    [8928] = "Trouvez un diablotin qui vivrait dans une caverne à l'entrée de la gorge du Sombre murmure, au sud du Berceau-de-l'hiver. Achetez-lui un Bâtonnet élémentaire de corruption, puis retournez voir Mux Manascrambler à Gadgetzan.",
    [8929] = "Utilisez le Révélateur de fantômes extradimensionnel à l’entrée de Stratholme et parlez au fantôme d’Anthion Harmon.",
    [8930] = "Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme, et parlez au fantôme d'Anthion Harmon.",
    [8945] = "Entrez à Stratholme et sauvez Ysida Harmon du baron Rivendare.",
    [8946] = "Remettre le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’est.",
    [8947] = "Remettre 3 Barres de sombre fer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l’est.",
    [8948] = "Apportez la Bannière de défi incomplète à Farlin Treeshaper, dans la bibliothèque de Hache-tripes.",
    [8949] = "Collecter 25 Perles de guerre ogres à l’intérieur de Hache-tripes ou du Pic Blackrock, puis revenir voir Falrin Treeshaper, à l'intérieur de l'Athenaeum à Hache-tripes.",
    [8950] = "Apportez les choses suivantes à Falrin Treeshaper dans Hache-tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants.",
    [8960] = "Rendez-vous au mont Blackrock, près du pic Blackrock, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.",
    [8961] = "Récupérez l’Incendicite d’Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu'un Brasero béni, puis retournez voir Bodley au mont Blackrock.",
    [8962] = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Blackrock.",
    [8963] = "Procurez-vous une Relique de Brise-stellaire et rapportez-la à Bodley, à l’intérieur du mont Blackrock.",
    [8964] = "Procurez-vous une Epée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Blackrock.",
    [8965] = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Blackrock.",
    [8966] = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Grayhoof, puis tuez-le. Ensuite, retournez voir Bodley à l'intérieur du mont Blackrock avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.",
    [8967] = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.",
    [8968] = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.",
    [8969] = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.",
    [8970] = "Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Blackrock.",
    [8977] = "Apportez le Révélateur de fantômes extradimensionnel à Deliana à Ironforge.",
    [8978] = "Retournez voir Mokvar à Orgrimmar avec le Révélateur de fantômes extradimensionnel.",
    [8985] = "Procurez-vous une Relique de Brise-stellaire et rapportez-la à Bodley, à l’intérieur du mont Blackrock.",
    [8986] = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Blackrock.",
    [8987] = "Procurez-vous une Epée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Blackrock.",
    [8988] = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Blackrock.",
    [8989] = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Grayhoof, puis tuez-le. Ensuite, retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8990] = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8991] = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos, puis tuez-les. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8992] = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8994] = "Collectez 40 Brassards blackrock et un Flacon de pouvoir suprême. Ensuite, retournez voir Bodley au mont Blackrock.",
    [8995] = "Utilisez le Brasero de signal pour invoquer le seigneur Valthalak. Tuez-le, puis utilisez l’Amulette du seigneur Valthalak sur le corps. Ensuite, rendez l’amulette à l’Esprit du seigneur Valthalak.",
    [8996] = "Retournez voir Bodley à l'intérieur du mont Blackrock et donnez-lui le Brasero de signal.",
    [8997] = "Parlez à Deliana au Haut Siège d'Ironforge.",
    [9015] = "Rendez-vous dans le Cercle de la loi, dans les profondeurs de Blackrock, et placez la Bannière de provocation en son centre lorsque vous serez $Gcondamné:condamnée; par le Juge supérieur Grimstone. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’est avec le premier morceau de l’amulette du seigneur Valthalak.",
    [9362] = "Récupérez la Coquille prismatique pour l'archimage Xylem. L'archimage réside dans une tour au sommet des falaises d'Azshara.",
    [9364] = "Métamorphosez les Fouette-bile d’Azshara, puis tuez les clones qui apparaissent quelques instants plus tard. Quand vous aurez tué 50 clones de métamorphose, retournez voir l’archimage Xylem en Azshara.",
