    [96379] = "Requirements:$B- Boîte à documents",
    [96381] = "Entrez dans la prison d’Alcaz et tuez 15 soldats strashaz, ainsi que 8 enchanteresses strashaz. Rapportez également la tête de la maîtresse des marées Ca’zass à Sully McCleary.",
    [96435] = "Jetez les os du démoniste sur le tas d’os près des bassins de limon.",
    [96770] = "Tuez le féticheur Zum’rah et rapportez sa tête à l’archimage Lan’dalock, à Dalaran.",
    [96771] = "Rendez-vous au bastion Krol’dok et terrassez Zalfan Lunombre.",
    [96772] = "Récupérez le journal de Zarla dans les profondeurs de la prison d’Alcaz.",
    [96774] = "Récupérez une idole antique des Gurubashi dans la cité Submergée.",
    [96775] = "Tuez le féticheur Zum’rah et rapportez sa tête à Mazu’kon, en Mulgore.",
    [96776] = "Récupérez le cristal connu sous le nom de radiance d’An’she, dans Maraudon.",
    [96779] = "Trouvez le seigneur Tomas dans le donjon de Fort-de-Durn, dans les contreforts de Hautebrande, et tuez-le. Revenez ensuite voir Myrokos Sourdeforme.",
    [96781] = "Volez le rapport d’éclaireur de Barton, puis rapportez-le à Myrokos Sourdeforme, au manoir de Ravenholdt.",
    [96782] = "Retrouvez la lame de la maison Perenolde et l’égide royale de Perenolde dans les ruines d’Alterac. Rapportez-les ensuite à Myrokos Sourdeforme.",
    [96783] = "Volez un uniforme du Syndicat au manoir de Nordclos afin d’infiltrer le donjon de Stromgarde.",
    [96784] = "Portez le déguisement d’un membre du Syndicat, puis trouvez quelqu’un qui soit au courant de la transaction secrète au donjon de Stromgarde.",
    [96785] = "Dans le donjon de Stromgarde, trouvez de quoi convaincre Anastasia de vous révéler les détails de cette transaction secrète.",
    [96786] = "Interrompez la transaction secrète et récupérez l’objet destiné au Syndicat. Rapportez-le ensuite à Myrokos Sourdeforme, au manoir de Ravenholdt.",
    [96800] = "Récupérez La Magie perdue des maîtres des runes au monastère Écarlate.",
    [96930] = "Retournez voir le corbeau curieux.",
    [96931] = "Touchez l’effigie de corbeau sur le pont qui surplombe le Berceau de la tranquillité pour appeler le dieu sauvage Jereman.",
    [96939] = "Parlez au dieu sauvage Marrosis.",
    [96964] = "Parlez au dieu sauvage Renalard.",
    [97022] = "Parlez à Danitha Morr à la Forteresse de Bandarion.",
    [97130] = "Récupérez une idole antique des Gurubashi dans la cité Submergée.",
    [97168] = "Si vous souhaitez aider Eldrun Stormbreaker à Forgefer, apportez-lui un diamant azérothien et un diamant noir immaculé.",
    [97169] = "Utilisez le Clairvoyant au cœur du sous-sol du Grand ossuaire, dans la Scholomance. Cela fera apparaître des esprits que vous devrez combattre. Leur défaite invoquera le Chevalier de la mort Darkreaver. Vainquez-le.$B$BApportez la tête de Darkreaver à Eldrun Stormbreaker dans la Caverne oubliée, à Forgefer.",
    [97173] = "Récupérez un totem rituel noiregueule au repaire des Noiregueules.",
    [97174] = "Parlez à Danitha Morr à la Forteresse de Bandarion, dans les Clairières de Tirisfal.",
    [97175] = "Rendez-vous à Orgrimmar et procurez-vous l’encensoir d’exorcisme du grand-prêtre Zayus. Vous devrez faire un don de 150 pièces d’or pour l’obtenir.",
    [97176] = "Utilisez l’encensoir d’exorcisme pour chasser les esprits tourmentés de Val-Terreur. Lorsque vous aurez détruit 25 esprits de Val-Terreur, retournez voir Danitha Morr à la Forteresse de Bandarion, dans les Clairières de Tirisfal.",
    [97177] = "Rapportez l’encensoir d’exorcisme à Danitha Morr à la forteresse de Bandarion, dans les clairières de Tirisfal.",
    [97178] = "Parlez à Ott, à Moulin-de-Tarren, dans les contreforts de Hautebrande.",
    [97179] = "Apportez 40 étoffes runiques, 6 barres d’arcanite, 10 larmes d’Arthas, 5 fioles d’eau bénite de Stratholme et 150 pièces d’or à Ott, dans les Contreforts de Hautebrande.",
    [97180] = "Apportez le caparaçon en arcanite à Danitha Morr à la forteresse de Bandarion afin qu’elle l’inspecte.",
    [97182] = "Procurez-vous une nourriture spéciale destinée aux chevaux spirituels. Nathanos le Flétrisseur, dans les Maleterres de l'est, pourrait vous en fournir.$B$BRendez-vous à Hache-tripes, en Feralas, et tuez Tendris Warpwood. Cela libérera l'ancien esprit équin. Donnez-lui la nourriture spéciale pour l’apaiser.$B$BEnfin, remettez-lui le caparaçon en arcanite et espérez qu’il accepte de vous accorder la bénédiction nécessaire.",
    [97183] = "Retournez voir Danitha Morr à la Forteresse de Bandarion, dans les Clairières de Tirisfal, avec le caparaçon en arcanite béni.",
    [97184] = "Rapportez un diamant d’Azeroth et un diamant noir en parfait état à Danitha Morr à la forteresse de Bandarion dans les clairières de Tirisfal.",
    [97185] = "Utilisez le clairvoyant au cœur des sous-sols du Grand ossuaire de Scholomance. Vous ferez ainsi apparaître les esprits qui devront répondre de leurs actes. En les vainquant, vous ferez venir le chevalier de la mort Ravassombre. Terrassez-le et récupérez l’âme égarée du destrier déchu.$B$BRemettez l’esprit de vindicte ainsi que le caparaçon enchanté béni au destrier déchu de Ravassombre.",
    [97186] = "Procurez-vous 20 biscuits de manne enrichis pour Nathanos le Flétrisseur, dans les Maleterres de l'est. L’Aube d’argent est connue pour être le seul fournisseur de ces biscuits. Vous devrez également donner 50 pièces d’or au Flétrisseur pour sa peine.",
    [97197] = "Récupérez un fragment des terres de Feu dans les profondeurs de Rochenoire pour Alaana Marchetempête, en Mulgore.",
    [97198] = "Récupérez un totem rituel noiregueule au repaire des Noiregueules.",
    [97243] = "Apportez la torche de la flamme dormante à Olariaan Vivebrûle au sanctuaire des Flammes, dans les plaines Aérelles.",
    [97244] = "Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur.",
    [97245] = "Trouvez le repaire de Kuramaa dans les hautes-terres de Shen’dar et vainquez l’esprit au combat. Une fois $Gvictorieux:victorieuse;, rapportez le masque de Kuramaa à Olariaan Vivebrûle dans les plaines Aérelles.",
    [97250] = "Tuez des soldats de l’Alliance qui empiètent sur les Tarides, à la frontière du marécage d’Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo.",
    [97257] = "Attendez qu’Olariaan commence le rituel au brasero d’offrande, puis suivez ses instructions.",
    [97288] = "Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse.",
    [97289] = "Apportez la tête du baron au corps d’Othmar, à Fossoyeuse.",
    [97290] = "Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse.",
    [97291] = "Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l’essence d’agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse.",
    [97292] = "Injectez le sérum sifflant dans le dispositif au-dessus du corps d’Othmar, pour le maître apothicaire Faranell.",
    [97327] = "Entrez dans le repaire des Noiregueules et récupérez 5 bourses noiregueules pour Ekkal, qui se trouve dans les ruines d’Eldarath en Azshara.",
    [97411] = "Procurez-vous 15 échantillons de venin de Silithus et 20 pièces d’or, puis apportez-les à Mokvar, à Orgrimmar, avec une paire de brassards sancteforge.",
    [97412] = "Apportez une ceinture de Sancteforge et une paire de gantelets de Sancteforge à Mokvar à Orgrimmar.",
    [97413] = "Retournez voir Mokvar à Orgrimmar avec des bottes sancteforge, des jambières sancteforge et des spallières sancteforge.",
    [97447] = "Procurez-vous 15 échantillons de sang du Berceau-de-l’hiver et 20 pièces d’or, et apportez-les avec une paire de manchettes des éléments à Deliana, à Forgefer.",
    [97448] = "Apportez une corde des éléments et une paire de gantelets des éléments à Deliana, à Forgefer.",
    [97449] = "Retournez voir Deliana à Forgefer avec des bottes des éléments, un kilt des éléments et des espauliers des éléments.",
    [98094] = "La grande exécutrice Darthalia vous charge de remettre des ordres mis à jour au nécrotraqueur Masoj, au sud de Moulin-de-Tarren, à l’extérieur de Dun Garok.",
    [98095] = "Le nécrotraqueur Masoj vous demande de placer les trois flacons d’apothicaire sur les hauteurs des contreforts de Hautebrande, puis de revenir le voir.",
    [98096] = "Trouvez la commandante Chantevrai à la halte de Talrendis, en Azshara, pour obtenir des informations sur ce qu’est devenue Keldara Lamesoleil.",
    [98298] = "Rapportez 6 morceaux worgens à Dalar Tisselaube au Sépulcre.",
    [98299] = "Tuez 5 réfugiés malades et 5 réfugiés hagards pour Dalar Tisselaube au Sépulcre.",
    [98325] = "Parlez au seigneur de guerre Sangredent pour vous mettre au service du corps expéditionnaire de Kargath.",
    [98340] = "Parlez à Dendrite Brasétoile au village de Havrenuit, à Reflet-de-Lune.",
    [98341] = "Partez à la recherche de l’avatar de Saeyleenan dans la partie sud de Reflet-de-Lune et découvrez ce qu’il peut vous apprendre sur la nature du félin du vent.",
    [98342] = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’esprit du Grand félin.",
    [98362] = "Retournez aux Pitons-du-Tonnerre et parlez à Turak Totem-runique, sur la cime des Anciens.",
    [98393] = "Parlez à Dendrite Brasétoile au village de Havrenuit, à Reflet-de-Lune.",
    [98394] = "Partez à la recherche de l’esprit du Grand félin dans la partie sud de Reflet-de-Lune, et découvrez ce qu’il peut vous apprendre sur la nature du félin.",
    [98396] = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’esprit du Grand félin.",
    [98397] = "Retournez à Darnassus et parlez à Mathrengyl Pasdelours, dans l’enclave Cénarienne.",
    [98404] = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’avatar de Saeyleenan.",
    [98405] = "Partez à la recherche de l’esprit du Grand félin dans la partie sud de Reflet-de-Lune, et découvrez ce qu’il peut vous apprendre sur la nature du félin.",
    [98447] = "Découvrez l’origine des fantômes de la famille Valor à la Colline-aux-Corbeaux pour Sirra Von’Indi, à Sombre-Comté.",
    [98512] = "Tuez 10 assassins al’aketh dans les hautes-terres de Shen’dar.",
    [98517] = "Allez voir Sessaria Marcheciel ou Aarnor Coup-de-Vent sur l’île de Zéphras pour poursuivre votre apprentissage de $Gchaman:chamane;.$B$BPour rentrer sur Zéphras, vous pouvez prendre le perceciel qui passe au plateau de Guette-ciel au nord-ouest des Pitons-du-Tonnerre, en Mulgore.",
    [98731] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [98738] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [98739] = "Parlez à Dendrite.",
    [98830] = "Apportez le glaive brisé de Tortheldrin à l’ancienne des Shen’dralar, à Hache-Tripes.",
    [99257] = "Tuez un protecteur de pylône décrépit pour obtenir son cœur de cristal épuisé et apportez-le à l’Historien Biraxas dans le temple de Shen’dralas.",
    [99258] = "Jetez le cœur de cristal épuisé dans une faille de mana instable. Retournez voir l’Historien Biraxas dans le temple de Shen’dralas avec la preuve de votre réussite ou de votre échec.",
    [99260] = "Parlez à Elaadrin Trombecalme, à Valanaar.",
    [99435] = "Suivez Reginald Windsor à travers Hurlevent. Protégez-le contre toute menace !\\n\\nParlez à l’Écuyer Rowe si vous devez de nouveau contacter Reginald Windsor.",
    [99670] = "Retournez voir Jereman au Berceau de la tranquillité.",
}
